 1	/**
 2	 * Singleton manager for cloud-provider authentication status (AWS Bedrock,
 3	 * GCP Vertex). Communicates auth refresh state between auth utilities and
 4	 * React components / SDK output. The SDK 'auth_status' message shape is
 5	 * provider-agnostic, so a single manager serves all providers.
 6	 *
 7	 * Legacy name: originally AWS-only; now used by all cloud auth refresh flows.
 8	 *
 9	 * Moved from packages/repl/src/awsAuthStatusManager.ts to break the
10	 * provider→repl back-edge that contributed to the 154-file SCC. Singleton
11	 * identity is preserved — all consumers (provider/userAuth, provider/authAlias,
12	 * cli/sdk, repl/AwsAuthStatusBox) now import from this canonical location.
13	 */
14	
15	import { createSignal } from '@thyrox/config/signal'
16	
17	export type AwsAuthStatus = {
18	  isAuthenticating: boolean
19	  output: string[]
20	  error?: string
21	}
22	
23	export class AwsAuthStatusManager {
24	  private static instance: AwsAuthStatusManager | null = null
25	  private status: AwsAuthStatus = {
26	    isAuthenticating: false,
27	    output: [],
28	  }
29	  private changed = createSignal<[status: AwsAuthStatus]>()
30	
31	  static getInstance(): AwsAuthStatusManager {
32	    if (!AwsAuthStatusManager.instance) {
33	      AwsAuthStatusManager.instance = new AwsAuthStatusManager()
34	    }
35	    return AwsAuthStatusManager.instance
36	  }
37	
38	  getStatus(): AwsAuthStatus {
39	    return {
40	      ...this.status,
41	      output: [...this.status.output],
42	    }
43	  }
44	
45	  startAuthentication(): void {
46	    this.status = {
47	      isAuthenticating: true,
48	      output: [],
49	    }
50	    this.changed.emit(this.getStatus())
51	  }
52	
53	  addOutput(line: string): void {
54	    this.status.output.push(line)
55	    this.changed.emit(this.getStatus())
56	  }
57	
58	  setError(error: string): void {
59	    this.status.error = error
60	    this.changed.emit(this.getStatus())
61	  }
62	
63	  endAuthentication(success: boolean): void {
64	    if (success) {
65	      this.status = {
66	        isAuthenticating: false,
67	        output: [],
68	      }
69	    } else {
70	      this.status.isAuthenticating = false
71	    }
72	    this.changed.emit(this.getStatus())
73	  }
74	
75	  subscribe = this.changed.subscribe
76	
77	  static reset(): void {
78	    if (AwsAuthStatusManager.instance) {
79	      AwsAuthStatusManager.instance.changed.clear()
80	      AwsAuthStatusManager.instance = null
81	    }
82	  }
83	}

